/** Slugs for generated project files and deployment names. */
/** Lowercase, dashes, alphanumerics only; `fallback` when nothing survives. */
export function slugify(name, fallback) {
    const slug = name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "");
    return slug === "" ? fallback : slug;
}
export const DEPLOYMENT_SLUG_PATTERN = /^[a-z0-9_-]{1,64}$/;
/** Derive a valid deployment slug from a directory name, or undefined if impossible. */
export function slugFromDirectoryName(name) {
    const slug = name
        .toLowerCase()
        .replace(/[^a-z0-9_-]+/g, "-")
        .replace(/^-+|-+$/g, "")
        .slice(0, 64);
    return DEPLOYMENT_SLUG_PATTERN.test(slug) ? slug : undefined;
}
/** Dedupes slugs with numeric suffixes: `linear`, `linear-2`, `linear-3`, … */
export class SlugRegistry {
    constructor() {
        this.used = new Set();
    }
    claim(base) {
        if (!this.used.has(base)) {
            this.used.add(base);
            return base;
        }
        for (let suffix = 2;; suffix++) {
            const candidate = `${base}-${suffix}`;
            if (!this.used.has(candidate)) {
                this.used.add(candidate);
                return candidate;
            }
        }
    }
}
